/** Capture the first-page name search response generated by the website. */
export async function dengkeResponse(tab, query, submitSearch) {
 if(typeof query!=='string'||!query.trim()||typeof submitSearch!=='function') throw Error('需要姓名关键词和正常检索回调');
 const q=query.trim(), c=await tab.capabilities.get('cdp'), methods=['Network.requestWillBeSent','Network.responseReceived','Network.loadingFinished'];
 await c.send('Network.enable');let cursor=(await c.readEvents({methods})).cursor;await submitSearch();let ids=new Set(),ok=new Set(),done=new Set();
 for(let deadline=Date.now()+25000;Date.now()<deadline;){
  let e=await c.readEvents({afterSequence:cursor,methods,limit:1000,timeoutMs:1000});cursor=e.cursor;if(e.truncated)throw Error('网络事件不完整');
  for(const v of e.events){let p=v.params||{};if(v.method==='Network.requestWillBeSent'&&p.request?.method==='GET'){let u;try{u=new URL(p.request.url)}catch{continue}if(u.origin==='https://examination.ancientbooks.cn'&&u.pathname==='/docDengke/dkSearchTable.jspx'&&u.searchParams.get('title')===q&&u.searchParams.get('type')==='fullName'&&u.searchParams.get('searchType')==='1'&&u.searchParams.get('bookType')==='0'&&u.searchParams.get('pageNo')==='1'&&u.searchParams.get('pageSize')==='15')ids.add(p.requestId)}if(v.method==='Network.responseReceived'&&p.response?.status===200&&p.response?.mimeType==='application/json')ok.add(p.requestId);if(v.method==='Network.loadingFinished')done.add(p.requestId)}
  let id=[...ids].find(x=>ok.has(x)&&done.has(x));if(!id)continue;
  let state=await tab.playwright.evaluate(()=>({host:location.hostname,path:location.pathname,text:document.body.innerText}));if(state.host!=='examination.ancientbooks.cn'||state.path!=='/docDengke/dkSearch.jspx'||!state.text.includes('当前机构: 浙江大学'))throw Error('当前页面或机构身份未匹配');
  let b=await c.send('Network.getResponseBody',{requestId:id});if(b.base64Encoded||!b.body)throw Error('无法读取检索响应');let d=JSON.parse(b.body);if(d.code!==0||!Number.isInteger(d.count)||!Array.isArray(d.data)||d.data.length>15)throw Error('响应结构异常');
  const clean=x=>typeof x==='string'?x.replace(/<\/?em>/g,''):x??null;
  let items=d.data.map(x=>({id:clean(x.content_id),name:clean(x.fullName),dynasty:clean(x.dynasty),subject:clean(x.subject),emperor:clean(x.emperor),birthplace:clean(x.sourceBirth),year:clean(x.annoDomini),reign_year:clean(x.yearName)}));if(items.some(x=>!x.id||!x.name))throw Error('题录缺少姓名或编号');
  return {source:'历代进士登科数据库',query:q,total:d.count,items,scope:'学校机构会话姓名检索首屏最多15条；详情、其他分页及逐条授权未验'};
 }
 throw Error('未捕获符合条件的进士姓名检索响应');
}
